import sys

def insertion_sort(arr):
    for i in range(1, len(arr)):
        key = arr[i]
        j = i - 1
        while j >= 0 and arr[j] > key:
            arr[j + 1] = arr[j]
            j -= 1
        arr[j + 1] = key

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    if n < 0:
        n = 0
    arr = [int(x) for x in data[1:1 + n]]
    insertion_sort(arr)
    print(' '.join(map(str, arr)))

if __name__ == '__main__':
    main()
